    }
  ];

  // ============================================
  // API CALL FUNCTIONS
  // ============================================

  const callApi = async (endpoint, method, body = null) => {
    try {
      const options = {
        method: method,
        headers: { 'Content-Type': 'application/json' }
      };
      if (body) {
        options.body = JSON.stringify(body);
      }
      const response = await fetch(`${API_BASE}${endpoint}`, options);
      const data = await response.json();

      console.log(`API ${method} ${endpoint}:`, data);

      return data;
    } catch (error) {
      console.error('API Error:', error);
      return null;
    }
  };

  // ============================================
  // LOAD SAVED STATE
  // ============================================

  useEffect(() => {
    try {
      const saved = localStorage.getItem('penziState');
      if (saved) {
        const parsed = JSON.parse(saved);

        if (parsed.currentUser && parsed.isLoggedIn) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
          setAllMatches(parsed.allMatches || []);
          setIncomingRequests(parsed.incomingRequests || []);
          setMyMatches(parsed.myMatches || []);
          setChatContacts(parsed.chatContacts || []);
          setChatMessages(parsed.chatMessages || {});
          setActiveTab(parsed.activeTab || 'discover');
          setMyPhone(parsed.myPhone || '0712345678');
          setActivationDone(true);
          setShowWelcomeBack(true);
          setShowMainMenu(true);
          setMatchOffset(parsed.matchOffset || 0);
          setTotalMatches(parsed.totalMatches || 0);
          setCompletedSteps(new Set(parsed.completedSteps || []));

          setTimeout(() => {
            addNotification(`👋 Welcome back, ${parsed.currentUser.name}!`);
          }, 500);

          setIsFirstTimeUser(false);
        } else {
          setCurrentStep(parsed.currentStep || 0);
          setCompletedSteps(new Set(parsed.completedSteps || []));
          setSmsConversation(parsed.smsConversation || []);
          setPhoneNumber(parsed.phoneNumber || '');
          setActivationDone(parsed.activationDone || false);
          setMyPhone(parsed.myPhone || '0712345678');
          if (parsed.currentUser) {
            setCurrentUser(parsed.currentUser);
          }
          setIsFirstTimeUser(true);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
      setIsFirstTimeUser(true);
    }
  }, []);

  // ============================================
  // SAVE STATE
  // ============================================

  useEffect(() => {
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        smsConversation,
        currentUser,
        isLoggedIn,
        phoneNumber,
        activationDone,
        allMatches,
        incomingRequests,
        myMatches,
        chatContacts,
        chatMessages,
        activeTab,
        myPhone,
        showMainMenu,
        searchCriteria,
        matchOffset,
        totalMatches
      };
      localStorage.setItem('penziState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, smsConversation, currentUser, isLoggedIn, phoneNumber, activationDone, allMatches, incomingRequests, myMatches, chatContacts, chatMessages, activeTab, myPhone, showMainMenu, searchCriteria, matchOffset, totalMatches]);

  // ============================================
  // CHECK SERVER
  // ============================================

  useEffect(() => {
    checkServer();
  }, []);

  const checkServer = async () => {
    try {
      const response = await fetch(`${API_BASE}/activate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ penzi: 'penzi' })
      });
      if (response.ok || response.status === 400 || response.status === 405) {
        setServerStatus('connected');
      } else {
        setServerStatus('error');
      }
    } catch (error) {
      setServerStatus('error');
    }
  };

  // ============================================
  // HELPERS
  // ============================================

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const addToConversation = (sender, message, isSystem = false) => {
    const entry = {
      id: Date.now(),
      sender: sender,
      message: message,
      isSystem: isSystem,
      timestamp: new Date().toLocaleTimeString()
    };
    setSmsConversation(prev => [...prev, entry]);
  };

  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  const getProgress = () => {
    if (!activationDone) return 0;
    return Math.round((completedSteps.size / STEPS.length) * 100);
  };

  const goToStep = (index) => {
    if (index >= 0 && index < STEPS.length) {
      setCurrentStep(index);
      setShowSystemResponse(false);
      setSystemResponseMessage('');
    }
  };

  // ============================================
  // LOGOUT / EXIT / HOME FUNCTIONS
  // ============================================

  const handleLogout = () => {
    localStorage.removeItem('penziState');
    setIsLoggedIn(false);
    setCurrentUser(null);
    setAllMatches([]);
    setIncomingRequests([]);
    setMyMatches([]);
    setChatContacts([]);
    setChatMessages({});
    setActiveChatUser(null);
    setSelectedChatContact(null);
    setSmsConversation([]);
    setActivationDone(false);
    setShowRegistrationComplete(false);
    setCurrentStep(0);
    setCompletedSteps(new Set());
    setMatchSearchActive(false);
    setShowWelcomeBack(false);
    setIsFirstTimeUser(true);
    setUserExistsError(false);
    setRegistrationError('');
    setShowMainMenu(false);
    setActiveMenuTab('register');
    setRegistrationComplete(false);
    setMatchOffset(0);
    setTotalMatches(0);
    setShowSystemResponse(false);
    setSystemResponseMessage('');
    addNotification('👋 Logged out successfully!');
  };

  const goHome = () => {
    setActiveTab('discover');
    setActiveChatUser(null);
    setSelectedChatContact(null);
    setShowProfile(false);
    setShowMatchDetails(false);
    setSelectedMatch(null);
    setMatchSearchActive(false);
    setShowMainMenu(true);
    addNotification('🏠 Returned to home');
  };

  const goToMenu = () => {
    setShowMainMenu(true);
    setActiveTab('discover');
  };

  // ============================================
  // EXECUTE API
  // ============================================

  const executeApi = async () => {
    const step = STEPS[currentStep];
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');
    setRegistrationError('');
    setUserExistsError(false);

    try {
      let phone = formData.phone_number || phoneNumber || myPhone || '0712345678';

      // STEP 1: SERVICE ACTIVATION
      if (step.isActivation) {
        const result = await callApi('/activate', 'POST', { penzi: formData.penzi || 'penzi' });
        if (result && result.status === 'success') {
          // Display system response exactly as per SMS flow
          setSystemResponseMessage(step.systemResponse);
          setShowSystemResponse(true);

          addToConversation('📱 You', 'PENZI', false);
          addToConversation('🤖 System', step.systemResponse, true);
          setActivationDone(true);
          setResponseMessage('✅ Service activated successfully!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Service activated!');
          setMyPhone('0712345678');
          setShowMainMenu(true);
        } else {
          setResponseMessage('❌ Activation failed. Please try again.');
          setIsSuccess(false);
          setErrorDetails('Invalid activation keyword. Please enter PENZI to continue.');
        }
      }

      // STEP 2: SERVICE REGISTRATION
      else if (step.isRegistration) {
        const data = {
          phone_number: formData.phone_number,
          name: formData.name,
          age: formData.age,
          gender: formData.gender,
          county: formData.county,
          town: formData.town
        };
        const result = await callApi('/register', 'POST', data);

        if (result && result.status === 'error' && result.message === 'User already exists') {
          // User exists - go directly to dashboard
          setUserExistsError(true);
          setRegistrationError('⚠️ User already exists. Proceeding to dashboard.');
          addNotification('⚠️ User already exists. Proceeding to dashboard.', 'warning');

          // Set user and go to dashboard
          const existingUser = {
            phone: formData.phone_number || phone || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(existingUser);
          setIsLoggedIn(true);
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
          setCompletedSteps(prev => new Set([...prev, currentStep]));

          // Add to conversation
          const userMsg = step.userMessage(formData);
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', '✅ User already exists! Proceeding to dashboard.', true);

          setIsLoading(false);
          return;
        }

        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemResponse(formData);

          setSystemResponseMessage(sysMsg);
          setShowSystemResponse(true);

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setMyPhone(formData.phone_number || '0712345678');
          setResponseMessage('✅ Registration complete!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete!');
          setRegistrationError('');

          // Set user and go to dashboard after registration
          const newUser = {
            phone: formData.phone_number || phone || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(newUser);
          setIsLoggedIn(true);
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
        } else {
          const errorMsg = result?.message || 'Registration failed. Please try again.';
          setResponseMessage('❌ ' + errorMsg);
          setIsSuccess(false);
          setRegistrationError(errorMsg);
        }
      }

      // STEP 3: DETAILS REGISTRATION
      else if (step.isDetails) {
        const data = {
          education_level: formData.education_level,
          profession: formData.profession,
          marital_status: formData.marital_status,
          religion: formData.religion,
          ethnicity: formData.ethnicity
        };
        const result = await callApi(`/${phone}/complete-profile`, 'POST', data);
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemResponse;

          setSystemResponseMessage(sysMsg);
          setShowSystemResponse(true);

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Profile completed!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Profile completed!');

          // Update current user with new details
          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              education: formData.education_level,
              profession: formData.profession,
              marital_status: formData.marital_status,
              religion: formData.religion,
              ethnicity: formData.ethnicity
            }));
          }
        } else {
          setResponseMessage('❌ ' + (result?.message || 'Profile completion failed.'));
          setIsSuccess(false);
        }
      }

      // STEP 4: SELF-DESCRIPTION
      else if (step.isSelfDescription) {
        const result = await callApi(`/${phone}/self-description`, 'POST', { description: formData.description });
        if (result && result.status === 'success') {
          const userMsg = step.userMessage(formData);
          const sysMsg = result.message || step.systemResponse;

          setSystemResponseMessage(sysMsg);
          setShowSystemResponse(true);

          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', sysMsg, true);
          setResponseMessage('✅ Self-description added!');
          setIsSuccess(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete!');
          setRegistrationComplete(true);

          // Update current user with description
          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              description: formData.description
            }));
          }

          // Ensure user is logged in
          if (!isLoggedIn) {
            const user = {
              phone: formData.phone_number || phone || '0712345678',
              name: formData.name || 'User',
              age: formData.age || '26',
              town: formData.town || 'Nairobi',
              county: formData.county || 'Nairobi',
              description: formData.description
            };
            setCurrentUser(user);
            setIsLoggedIn(true);
          }
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
          addNotification('🎉 Welcome to PENZI Dating!');
        } else {
          setResponseMessage('❌ ' + (result?.message || 'Self-description failed.'));
          setIsSuccess(false);
        }
      }

    } catch (error) {
      console.error('❌ API Error:', error);
      setResponseMessage('❌ Network error. Please check your connection.');
      setIsSuccess(false);
      setErrorDetails(error.message);
      addNotification('❌ Network error', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // ============================================
  // RENDER SMS CONVERSATION
  // ============================================

  const renderSmsConversation = () => {
    if (smsConversation.length === 0) return null;
    return (
      <div className="sms-conversation-container">
        <div className="sms-conversation-header">
          <span className="conversation-title">💬 SMS Conversation</span>
          <span className="conversation-count">{smsConversation.length} messages</span>
        </div>
        <div className="sms-conversation">
          {smsConversation.map((msg) => (
            <div key={msg.id} className={`sms-conversation-bubble ${msg.isSystem ? 'system' : 'user'}`}>
              <div className="sms-sender">{msg.sender}</div>
              <div className="sms-message">{msg.message}</div>
              <div className="sms-time">{msg.timestamp}</div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER SYSTEM RESPONSE
  // ============================================

  const renderSystemResponse = () => {
    if (!showSystemResponse || !systemResponseMessage) return null;

    return (
      <div className="system-response-card">
        <div className="response-title">🤖 System Response</div>
        <div className="response-body">{systemResponseMessage}</div>
      </div>
    );
  };

  // ============================================
  // RENDER MAIN MENU
  // ============================================

  const renderMainMenu = () => {
    const isRegistered = completedSteps.has(0) || activationDone;
    const hasProfile = completedSteps.has(2);
    const hasDescription = completedSteps.has(3);

    return (
      <div className="main-menu-container">
        <div className="main-menu-header">
          <h1>💑 PENZI Dating</h1>
          <p className="menu-subtitle">Find your perfect match</p>
          {currentUser && (
            <div className="menu-user-info">
              <span>👋 Welcome, {currentUser.name || 'User'}!</span>
            </div>
          )}
        </div>

        <div className="main-menu-options">
          {/* Find Matches - Always Active */}
          <div className="menu-card find-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('discover');
            setActiveMenuTab('matches');
            // Load sample data if no matches
            if (allMatches.length === 0) {
              setAllMatches(SAMPLE_MATCHES);
              setSearchCriteria({ ageRange: '20-40', town: '', county: '' });
              addNotification(`✅ Found ${SAMPLE_MATCHES.length} matches!`);
            }
          }}>
            <div className="menu-card-icon">❤️</div>
            <div className="menu-card-content">
              <h3>Find Matches</h3>
              <p>Search based on Age, Town & County</p>
              <span className="menu-card-sub">Discover your perfect match</span>
            </div>
            <div className="menu-card-arrow">→</div>
          </div>

          {/* View Your Profile - Replaces "Complete Profile" */}
          <div className="menu-card profile-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('discover');
            setShowProfile(true);
            setActiveMenuTab('profile');
          }}>
            <div className="menu-card-icon">👤</div>
            <div className="menu-card-content">
              <h3>View Your Profile</h3>
              <p>See and update your profile information</p>
              {hasProfile && hasDescription && <span className="menu-card-badge">✅ Complete</span>}
              {(!hasProfile || !hasDescription) && <span className="menu-card-badge inactive">⏳ Incomplete</span>}
            </div>
            <div className="menu-card-arrow">→</div>
          </div>
        </div>

        <div className="quick-search-preview">
          <div className="quick-search-header">
            <span>🔍 Quick Search</span>
          </div>
          <div className="quick-search-fields">
            <div className="quick-search-field">
              <label>Age Range</label>
              <input type="text" placeholder="20-40" id="qs-age" className="qs-input" defaultValue="20-40" />
            </div>
            <div className="quick-search-field">
              <label>Town</label>
              <input type="text" placeholder="Nairobi" id="qs-town" className="qs-input" />
            </div>
            <div className="quick-search-field">
              <label>County</label>
              <input type="text" placeholder="Nairobi County" id="qs-county" className="qs-input" />
            </div>
            <button className="qs-btn" onClick={() => {
              const ageRange = document.getElementById('qs-age')?.value || '20-40';
              const town = document.getElementById('qs-town')?.value || '';
              const county = document.getElementById('qs-county')?.value || '';

              // Filter sample data based on criteria
              let filtered = SAMPLE_MATCHES;
              if (ageRange && ageRange !== '') {
                const [min, max] = ageRange.split('-').map(Number);
                if (!isNaN(min) && !isNaN(max)) {
                  filtered = filtered.filter(m => m.age >= min && m.age <= max);
                }
              }
              if (town && town !== '') {
                filtered = filtered.filter(m => m.town.toLowerCase().includes(town.toLowerCase()));
              }
              if (county && county !== '') {
                filtered = filtered.filter(m => m.county && m.county.toLowerCase().includes(county.toLowerCase()));
              }
              setAllMatches(filtered);
              setSearchCriteria({ ageRange, town, county });
              setShowMainMenu(false);
              setActiveTab('discover');
              addNotification(`✅ Found ${filtered.length} matches!`);
            }}>
              🔍 Search
            </button>
          </div>
        </div>

        <div className="main-menu-footer">
          <button className="btn-exit" onClick={handleLogout}>🚪 Exit</button>
          <span className="menu-version">v1.0 • PENZI Dating</span>
        </div>
      </div>
    );
