  // ============================================
  // RENDER REGISTRATION
  // ============================================

  const renderRegistration = () => {
    const step = STEPS[currentStep];
    const isActivationStep = step.isActivation;
    const showUserExistsWarning = userExistsError;
    const isLastStepCompleted = step.isSelfDescription && completedSteps.has(currentStep);

    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="top-actions">
            {isLoggedIn && (
              <button className="btn-top btn-home" onClick={goHome}>🏠 Home</button>
            )}
            <button className="btn-top btn-exit" onClick={handleLogout}>🚪 Exit</button>
          </div>

          {showWelcomeBack && (
            <div className="welcome-back-banner">
              <div className="welcome-back-icon">👋</div>
              <div className="welcome-back-text">
                <h3>Welcome Back!</h3>
                <p>Continue your dating journey</p>
              </div>
              <button className="btn-primary btn-continue" onClick={() => {
                setIsLoggedIn(true);
                setShowMainMenu(true);
              }}>
                Continue →
              </button>
            </div>
          )}

          <div className="registration-header">
            <div className="registration-icon">{step.icon}</div>
            <h1>PENZI Dating</h1>
            <p className="subtitle">Find your perfect match</p>
          </div>

          <div className={`server-status ${serverStatus}`}>
            <span className="status-dot"></span>
            <span className="status-text">
              {serverStatus === 'connected' ? '✅ Server Connected' : 
               serverStatus === 'checking' ? '⏳ Checking...' : 
               '❌ Server Not Connected'}
            </span>
          </div>

          {activationDone && (
            <div className="progress-bar-container">
              <div className="progress-bar">
                <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
              </div>
              <span className="progress-text">{getProgress()}% Complete • {completedSteps.size}/{STEPS.length}</span>
            </div>
          )}

          {renderSmsConversation()}

          <div className="step-info-card">
            <div className="step-number">
              {isActivationStep ? '🔑 ENTRY POINT' : `Step ${currentStep + 1} of ${STEPS.length}`}
            </div>
            <h2>{step.title}</h2>
            <p>{step.subtitle}</p>
          </div>

          {showUserExistsWarning && (
            <div className="user-exists-warning">
              <div className="warning-icon">⚠️</div>
              <div className="warning-content">
                <div className="warning-title">User Already Exists</div>
                <div className="warning-text">{registrationError}</div>
              </div>
            </div>
          )}

          {registrationError && !userExistsError && (
            <div className="registration-error">
              <span className="error-icon">⚠️</span>
              <span className="error-text">{registrationError}</span>
            </div>
          )}

          {/* STEP 1: Activation - Special UI */}
          {isActivationStep && (
            <div className="activation-keyword-display">
              <span className="keyword-label">📱 Activation Keyword</span>
              <span className="keyword-code">PENZI</span>
              <span className="keyword-hint">Enter this keyword to activate the service</span>
            </div>
          )}

          {/* System Response Display */}
          {renderSystemResponse()}

          <form onSubmit={(e) => { e.preventDefault(); executeApi(); }} className="registration-form">

            {/* Fields for non-activation steps */}
            {!isActivationStep && step.fields && step.fields.map((field) => (
              <div key={field.key} className="input-group">
                <label>{field.label}</label>
                {field.type === 'select' ? (
                  <select
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    className="input-field"
                    required={!userExistsError}
                    disabled={userExistsError}
                  >
                    <option value="">Select {field.label}</option>
                    {field.options.map(opt => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                ) : field.type === 'textarea' ? (
                  <textarea
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="textarea-field"
                    rows={4}
                    required={!userExistsError}
                    disabled={userExistsError}
                  />
                ) : (
                  <input
                    type={field.type || 'text'}
                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="input-field"
                    required={!userExistsError}
                    disabled={userExistsError}
                  />
                )}
              </div>
            ))}

            {/* Hidden field for activation step - just show the keyword */}
            {isActivationStep && (
              <input type="hidden" name="penzi" value="PENZI" />
            )}

            {/* SMS Preview for non-activation steps */}
            {!isActivationStep && step.userMessage && formData && Object.keys(formData).length > 0 && (
              <div className="sms-preview-container">
                <div className="sms-preview-label">📱 Your SMS will be:</div>
                <div className="sms-preview-content">
                  {typeof step.userMessage === 'function' ? step.userMessage(formData) : ''}
                </div>
              </div>
            )}

            <div className="registration-actions">
              {/* Previous Button */}
              <button
                type="button"
                onClick={() => goToStep(currentStep - 1)}
                disabled={currentStep === 0 || isLoading || !activationDone || userExistsError}
                className="btn-secondary"
              >
                ⬅ Previous
              </button>

              {/* Main Action Button - changes based on step */}
              {isActivationStep ? (
                // Activation Step: Show Activate button, disable after activation
                <button
                  type="submit"
                  disabled={isLoading || serverStatus === 'error' || activationDone}
                  className={`btn-primary ${isLoading ? 'loading' : ''}`}
                >
                  {isLoading ? '⏳ Activating...' : '💑 Activate Service'}
                </button>
              ) : (
                // Non-activation steps: Show Send button
                <button
                  type="submit"
                  disabled={isLoading || serverStatus === 'error' || userExistsError}
                  className={`btn-primary ${isLoading ? 'loading' : ''}`}
                >
                  {isLoading ? '⏳ Sending...' : '📤 Send'}
                </button>
              )}

              {/* Next/Continue Button - replaces previous "Next" button */}
              <button
                type="button"
                onClick={() => {
                  // If user exists error, go directly to dashboard
                  if (userExistsError) {
                    setCompletedSteps(prev => new Set([...prev, currentStep]));
                    setShowMainMenu(true);
                    setIsLoggedIn(true);
                    setUserExistsError(false);
                    setRegistrationError('');
                    return;
                  }

                  // If activation is done and on step 1, go to registration
                  if (isActivationStep && activationDone) {
                    goToStep(currentStep + 1);
                    setShowSystemResponse(false);
                    return;
                  }

                  // If registration step is completed, go to next step
                  if (currentStep < STEPS.length - 1 && completedSteps.has(currentStep)) {
                    goToStep(currentStep + 1);
                    setShowSystemResponse(false);
                    return;
                  }

                  // If on last step and completed, go to menu
                  if (currentStep === STEPS.length - 1 && completedSteps.has(currentStep)) {
                    setShowMainMenu(true);
                    setIsLoggedIn(true);
                    return;
                  }
                }}
                disabled={
                  isLoading || 
                  (!isActivationStep && !completedSteps.has(currentStep) && !userExistsError) ||
                  (isActivationStep && !activationDone)
                }
                className="btn-secondary"
              >
                {isActivationStep && activationDone ? '📝 Start Registration →' :
                 userExistsError ? '📋 Go to Dashboard' :
                 currentStep === STEPS.length - 1 && completedSteps.has(currentStep) ? '📋 Go to Menu' :
                 currentStep < STEPS.length - 1 && completedSteps.has(currentStep) ? 'Next →' :
                 'Next →'}
              </button>
            </div>
          </form>

          {userExistsError && (
            <div className="user-exists-help">
              <p>💡 Click <strong>📋 Go to Dashboard</strong> to proceed to find matches.</p>
            </div>
          )}

          {isLastStepCompleted && !showUserExistsWarning && (
            <div className="registration-complete-prompt">
              <p>🎉 Registration complete! Click <strong>📋 Go to Menu</strong> to continue.</p>
            </div>
          )}

          {errorDetails && (
            <div className="error-details">
              <p className="error-detail-text">💡 {errorDetails}</p>
            </div>
          )}

          {responseMessage && (
            <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
              {responseMessage}
            </div>
          )}

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER NOTIFICATIONS
  // ============================================

  const renderNotifications = () => {
    if (notifications.length === 0) return null;
    return (
      <div className="notifications-container">
        {notifications.map((notif) => (
          <div key={notif.id} className={`notification ${notif.type || 'success'}`}>
            {notif.message}
          </div>
        ))}
      </div>
    );
  };

  // ============================================
  // RENDER PROFILE MODAL
  // ============================================

  const renderProfileModal = () => {
    if (!selectedMatch || !showMatchDetails) return null;

    return (
      <div className="modal-overlay" onClick={() => { setShowMatchDetails(false); setSelectedMatch(null); }}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => { setShowMatchDetails(false); setSelectedMatch(null); }}>✕</button>

          <div className="profile-header">
            <div className="profile-avatar">{selectedMatch.name?.charAt(0) || '?'}</div>
            <h2>{selectedMatch.name}</h2>
            <p>{selectedMatch.age} years • {selectedMatch.town}</p>
          </div>

          <div className="profile-details">
            <div className="profile-item"><span className="label">📞 Phone</span><span>{selectedMatch.phone}</span></div>
            <div className="profile-item"><span className="label">📍 County</span><span>{selectedMatch.county || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">💼 Profession</span><span>{selectedMatch.profession || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🎓 Education</span><span>{selectedMatch.education || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">💍 Marital Status</span><span>{selectedMatch.marital_status || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🙏 Religion</span><span>{selectedMatch.religion || 'Not specified'}</span></div>
            <div className="profile-item"><span className="label">🌍 Ethnicity</span><span>{selectedMatch.ethnicity || 'Not specified'}</span></div>
            {selectedMatch.description && (
              <div className="profile-item full-width">
                <span className="label">💭 About Me</span>
                <span>{selectedMatch.description}</span>
              </div>
            )}
          </div>

          <div className="modal-actions">
            <button className="btn-secondary" onClick={() => { setShowMatchDetails(false); setSelectedMatch(null); }}>
              Close
            </button>
            <button 
              className="btn-primary" 
              onClick={() => {
                // Express interest logic
                addNotification(`💕 Interest sent to ${selectedMatch.name}!`);
                setShowMatchDetails(false);
                setSelectedMatch(null);
              }}
            >
              💕 Express Interest
            </button>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER CHAT
  // ============================================

  const renderChat = () => {
    if (selectedChatContact) {
      const messages = chatMessages[selectedChatContact.phone] || [];

      return (
        <div className="chat-view">
          <div className="chat-header-whatsapp">
            <div className="chat-header-left">
              <button className="btn-back-chat" onClick={() => setSelectedChatContact(null)}>←</button>
              <div className="chat-avatar">{selectedChatContact.name?.charAt(0) || '?'}</div>
              <div className="chat-contact-info">
                <div className="chat-contact-name">{selectedChatContact.name}</div>
                <div className="chat-contact-status">
                  {selectedChatContact.online ? '🟢 Online' : 'Last seen recently'}
                </div>
              </div>
            </div>
            <div className="chat-header-right">
              <button className="btn-chat-action">👤</button>
            </div>
          </div>

          <div className="chat-messages-whatsapp">
            {messages.length === 0 ? (
              <div className="empty-state">
                <div className="empty-icon">💬</div>
                <h3>No Messages Yet</h3>
                <p>Start a conversation with {selectedChatContact.name}</p>
              </div>
            ) : (
              messages.map((msg) => (
                <div key={msg.id} className={`message-bubble ${msg.isMine ? 'sent' : 'received'}`}>
                  {!msg.isMine && <div className="message-sender">{msg.sender}</div>}
                  <div className="message-content">
                    <p>{msg.message}</p>
                    <span className="message-time">{msg.time}</span>
                    {msg.isMine && msg.status === 'sending' && (
                      <span className="message-status">⏳</span>
                    )}
                    {msg.isMine && msg.status === 'sent' && (
                      <span className="message-status">✓</span>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>

          <div className="chat-input-whatsapp">
            <input
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              placeholder={`Message ${selectedChatContact.name}...`}
              onKeyPress={(e) => {
                if (e.key === 'Enter') {
                  // Send message logic
                }
              }}
              disabled={isSendingMessage}
            />
            <button 
              className="btn-send-whatsapp" 
              onClick={() => {
                if (!newMessage.trim()) return;
                const msg = {
                  id: Date.now(),
                  sender: 'You',
                  message: newMessage,
                  time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                  isMine: true,
                  status: 'sent'
                };
                setChatMessages(prev => ({
                  ...prev,
                  [selectedChatContact.phone]: [...(prev[selectedChatContact.phone] || []), msg]
                }));
                setNewMessage('');
              }}
              disabled={!newMessage.trim() || isSendingMessage}
            >
              {isSendingMessage ? '⏳' : '📤'}
            </button>
          </div>
        </div>
      );
    }

    return (
      <div className="chat-contact-list-whatsapp">
        <div className="chat-list-header-whatsapp">
          <h3>💬 Chats</h3>
          <span className="chat-list-count">{chatContacts.length} chats</span>
