        <div className="empty-state">
          <div className="empty-icon">💕</div>
          <h2>No Matches Yet</h2>
          <p>Start discovering and accepting requests to find your match</p>
          <div className="empty-actions">
            <button className="btn-primary" onClick={() => {
              setMyMatches(SAMPLE_MY_MATCHES);
              addNotification(`✅ Loaded ${SAMPLE_MY_MATCHES.length} matches!`);
            }}>
              📥 Load Sample Matches
            </button>
            <button className="btn-secondary" onClick={() => setActiveTab('discover')}>
              🔍 Discover People
            </button>
          </div>
        </div>
      );
    }

    return (
      <div className="discover-table-container">
        <div className="table-header">
          <div className="table-header-left">
            <h3>💕 Your Matches</h3>
            <span className="match-count">{myMatches.length} matches</span>
          </div>
        </div>

        <div className="matches-table-wrapper">
          <table className="matches-table">
            <thead>
              <tr>
                <th>#</th>
                <th>Name</th>
                <th>Age</th>
                <th>Town</th>
                <th>County</th>
                <th>Profession</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {myMatches.map((match, index) => (
                <tr key={match.id} className="match-row">
                  <td className="match-number">{index + 1}</td>
                  <td className="match-name-cell">
                    <div className="match-avatar-small" onClick={() => {
                      setSelectedMatch(match);
                      setShowMatchDetails(true);
                    }}>
                      {match.name?.charAt(0) || '?'}
                    </div>
                    <span className="match-name-text" onClick={() => {
                      setSelectedMatch(match);
                      setShowMatchDetails(true);
                    }}>
                      {match.name}
                    </span>
                  </td>
                  <td>{match.age}</td>
                  <td>{match.town}</td>
                  <td>{match.county || 'N/A'}</td>
                  <td>{match.profession || 'N/A'}</td>
                  <td><span className="status-accepted">✅ Accepted</span></td>
                  <td className="match-actions-cell">
                    <button className="btn-view" onClick={() => {
                      setSelectedMatch(match);
                      setShowMatchDetails(true);
                    }}>👤</button>
                    <button className="btn-chat" onClick={() => {
                      // Start chat
                      if (!chatContacts.some(c => c.phone === match.phone)) {
                        const newContact = {
                          phone: match.phone,
                          name: match.name,
                          lastMessage: 'Start chatting...',
                          lastMessageTime: 'Now',
                          unread: 0,
                          online: true
                        };
                        setChatContacts(prev => [newContact, ...prev]);
                      }
                      setSelectedChatContact(match);
                      setActiveTab('chat');
                      addNotification(`💬 Chat started with ${match.name}`);
                    }}>💬</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="table-navigation">
          <button 
            className="nav-btn"
            onClick={() => setCurrentMatchListIndex(Math.max(0, currentMatchListIndex - 5))}
            disabled={currentMatchListIndex === 0}
          >
            ⬅ Previous
          </button>
          <span className="match-counter">
            {currentMatchListIndex + 1} of {myMatches.length}
          </span>
          <button 
            className="nav-btn"
            onClick={() => setCurrentMatchListIndex(Math.min(myMatches.length - 1, currentMatchListIndex + 5))}
            disabled={currentMatchListIndex >= myMatches.length - 1}
          >
            Next ➡
          </button>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER PROFILE DETAILS (View Your Profile)
  // ============================================

  const renderProfileDetails = () => {
    if (!currentUser) return null;

    return (
      <div className="modal-overlay" onClick={() => { setShowProfile(false); setIsEditingProfile(false); }}>
        <div className="modal-content" onClick={(e) => e.stopPropagation()}>
          <button className="modal-close" onClick={() => { setShowProfile(false); setIsEditingProfile(false); }}>✕</button>

          <div className="profile-header">
            <div className="profile-avatar">{currentUser.name?.charAt(0) || '?'}</div>
            <h2>{currentUser.name}</h2>
            <p>{currentUser.age || '?'} years • {currentUser.town || 'Unknown'}</p>
          </div>

          {!isEditingProfile ? (
            // View Mode
            <>
              <div className="profile-details">
                <div className="profile-item"><span className="label">📞 Phone</span><span>{currentUser.phone}</span></div>
                <div className="profile-item"><span className="label">📍 County</span><span>{currentUser.county || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">💼 Profession</span><span>{currentUser.profession || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🎓 Education</span><span>{currentUser.education || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">💍 Marital Status</span><span>{currentUser.marital_status || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🙏 Religion</span><span>{currentUser.religion || 'Not specified'}</span></div>
                <div className="profile-item"><span className="label">🌍 Ethnicity</span><span>{currentUser.ethnicity || 'Not specified'}</span></div>
                {currentUser.description && (
                  <div className="profile-item full-width">
                    <span className="label">💭 About Me</span>
                    <span>{currentUser.description}</span>
                  </div>
                )}
              </div>
              <div className="modal-actions">
                <button className="btn-primary" onClick={() => setIsEditingProfile(true)}>
                  ✏️ Edit Profile
                </button>
                <button className="btn-secondary" onClick={() => { setShowProfile(false); setIsEditingProfile(false); }}>
                  Close
                </button>
              </div>
            </>
          ) : (
            // Edit Mode
            <form onSubmit={(e) => {
              e.preventDefault();
              // Update profile logic here
              setIsEditingProfile(false);
              addNotification('✅ Profile updated successfully!');
            }}>
              <div className="profile-details">
                <div className="input-group">
                  <label>👤 Name</label>
                  <input type="text" className="input-field" defaultValue={currentUser.name} />
                </div>
                <div className="input-group">
                  <label>🎂 Age</label>
                  <input type="number" className="input-field" defaultValue={currentUser.age} />
                </div>
                <div className="input-group">
                  <label>📍 County</label>
                  <input type="text" className="input-field" defaultValue={currentUser.county || ''} />
                </div>
                <div className="input-group">
                  <label>💼 Profession</label>
                  <input type="text" className="input-field" defaultValue={currentUser.profession || ''} />
                </div>
                <div className="input-group">
                  <label>🎓 Education</label>
                  <select className="input-field" defaultValue={currentUser.education || ''}>
                    <option value="">Select Education</option>
                    <option value="Primary">Primary</option>
                    <option value="Secondary">Secondary</option>
                    <option value="Certificate">Certificate</option>
                    <option value="Diploma">Diploma</option>
                    <option value="Graduate">Graduate</option>
                    <option value="Post Graduate">Post Graduate</option>
                  </select>
                </div>
                <div className="input-group">
                  <label>💍 Marital Status</label>
                  <select className="input-field" defaultValue={currentUser.marital_status || ''}>
                    <option value="">Select Status</option>
                    <option value="single">Single</option>
                    <option value="married">Married</option>
                    <option value="divorced">Divorced</option>
                    <option value="widowed">Widowed</option>
                    <option value="separated">Separated</option>
                  </select>
                </div>
                <div className="input-group">
                  <label>🙏 Religion</label>
                  <input type="text" className="input-field" defaultValue={currentUser.religion || ''} />
                </div>
                <div className="input-group">
                  <label>🌍 Ethnicity</label>
                  <input type="text" className="input-field" defaultValue={currentUser.ethnicity || ''} />
                </div>
                <div className="input-group">
                  <label>💭 About Me</label>
                  <textarea className="textarea-field" rows="3" defaultValue={currentUser.description || ''} />
                </div>
              </div>
              <div className="modal-actions">
                <button type="submit" className="btn-primary">💾 Save</button>
                <button type="button" className="btn-secondary" onClick={() => setIsEditingProfile(false)}>Cancel</button>
              </div>
            </form>
          )}
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER DASHBOARD
  // ============================================

  const renderDashboard = () => {
    return (
      <div className="dashboard-container">
        <header className="dashboard-header">
          <div className="header-left">
            <button className="btn-home" onClick={goHome} title="Home">🏠</button>
            <h1>💑 PENZI</h1>
            <span className="live-badge">❤️ Live</span>
          </div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name || 'User'}</span>
            <button className="btn-menu" onClick={() => setShowMainMenu(true)} title="Menu">📋</button>
            <button className="profile-btn" onClick={() => setShowProfile(true)} title="View Profile">👤</button>
            <button className="btn-exit" onClick={handleLogout} title="Logout">🚪</button>
          </div>
        </header>

        <nav className="dashboard-nav">
          <button 
            className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('discover');
              if (allMatches.length === 0) {
                setAllMatches(SAMPLE_MATCHES);
                setSearchCriteria({ ageRange: '20-40', town: '', county: '' });
              }
            }}
          >
            🔍 Discover
            <span className="nav-badge">{allMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('matches');
              if (myMatches.length === 0) {
                setMyMatches(SAMPLE_MY_MATCHES);
              }
            }}
          >
            💕 Matches
            <span className="nav-badge">{myMatches.length}</span>
          </button>
          <button 
            className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`} 
            onClick={() => {
              setActiveTab('requests');
              if (incomingRequests.length === 0) {
                setIncomingRequests(SAMPLE_REQUESTS);
              }
            }}
          >
            📬 Requests
            {incomingRequests.length > 0 && <span className="nav-badge red">{incomingRequests.length}</span>}
          </button>
          <button 
            className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`} 
            onClick={() => setActiveTab('chat')}
          >
            💬 Chat
            {chatContacts.length > 0 && <span className="nav-badge">{chatContacts.length}</span>}
          </button>
        </nav>

        <main className="dashboard-content">
          {activeTab === 'discover' && renderDiscoverTable()}
          {activeTab === 'matches' && renderMyMatchesTable()}
          {activeTab === 'requests' && renderRequestsTable()}
          {activeTab === 'chat' && (
            <div className="chat-container-whatsapp">
              {renderChat()}
            </div>
          )}
        </main>

        {showMatchDetails && renderProfileModal()}
        {showProfile && renderProfileDetails()}
      </div>
    );
  };

  // ============================================
  // MAIN RETURN
  // ============================================

  return (
    <div className="app">
      {renderNotifications()}
      {isLoggedIn ? (
        showMainMenu ? renderMainMenu() : renderDashboard()
      ) : (
        renderRegistration()
      )}
    </div>
  );
}

export default App;
